  for(unsigned index:{1u,6u}){auto bird=a.placements.at(index);bird.packed=uint32_t(0x46DA)<<16|(index==1?0:1);bird.origin=Origin::NativePointCopy;a.placements.push_back(bird);}preload(a,0x46DA);
