struct Observer::Impl {
 Plan plan;Snapshot s;std::array<f::CandyMemberObserver,2> candy;std::array<f::MemberObserver,2> family;
 struct Pending{unsigned member=2,before=0,vi=0;uint32_t stack=0;uint64_t birth=0;} damage;
 struct Pulse{uint32_t source=0,private_data=0;unsigned hit_mask=0;uint64_t serial=0;};std::map<uint32_t,Pulse> pulses;uint64_t serial=0;std::array<unsigned,2> last_hit{};std::array<bool,2> retire_pending{},marmot_terminal{};std::vector<RetireAction> actions;
 uint32_t bowser_stack=0;unsigned bowser_vi=0,last_frame_vi=0;bool frame_seen=false;
 bool scope(const Frame& f)const{return s.enabled&&!s.failed&&f.epoch==s.epoch&&f.room==s.room&&(!frame_seen||f.vi>=last_frame_vi);}
 void fail(const char* why){s.failed=true;s.ready_to_exit=false;s.failure=why;}
 bool live(uint8_t* r,unsigned m)const{const auto& b=s.members[m];return b.actor&&n::actor(r,b.actor,kinds[s.bonus-1])&&(!b.private_data||n::word(r,b.actor+0x1F4)==b.private_data);}
 void finish(unsigned m){auto& b=s.members[m];if(!b.defeated){b.defeated=true;++s.defeated;s.ready_to_exit=s.defeated==s.expected;}}
 void harvest(){for(unsigned m=0;m<s.expected;++m){if(plan.family==Family::Candy||plan.family==Family::Lips||plan.family==Family::Genie){const auto& e=plan.family==Family::Candy?candy[m].snapshot().actors[0]:family[m].snapshot().actors[0];s.members[m].private_data=e.private_data;s.members[m].initialized=e.initialized;s.members[m].active=e.active_seen;s.members[m].hits=e.causal_hits;if(e.counter>=0)s.members[m].remaining=unsigned(e.counter);}if(plan.family==Family::Candy){if(candy[m].snapshot().invalidated){fail("native_candy_evidence_rejected");return;}if(candy[m].take_defeat_observation())finish(m);}else if(plan.family==Family::Lips||plan.family==Family::Genie){if(family[m].snapshot().invalidated){fail("native_family_evidence_rejected");return;}if(family[m].take_defeat_observation())finish(m);}}}
};
Observer::Observer():impl_(std::make_unique<Impl>()){}Observer::~Observer()=default;Observer::Observer(Observer&&)noexcept=default;Observer& Observer::operator=(Observer&&)noexcept=default;
bool Observer::configure(const Plan& p,std::string token,uint64_t epoch,unsigned room){*impl_=Impl{};if(!valid(p)||!epoch||token.empty()||std::none_of(p.arenas.begin(),p.arenas.end(),[&](const auto& a){return a.room==room;}))return false;auto& i=*impl_;i.plan=p;i.s.enabled=true;i.s.epoch=epoch;i.s.bonus=p.bonus;i.s.room=room;i.s.expected=p.members;boss_battle0250::Encounter e;e.number=1;e.count=p.members;for(unsigned m=0;m<p.members;++m){e.members[m].kind=kinds[p.bonus-1];e.members[m].hits=p.family==Family::Candy?12:3;bool okay=true;if(p.family==Family::Candy)okay=i.candy[m].configure(e,m,token,room,false);else if(p.family==Family::Lips||p.family==Family::Genie)okay=i.family[m].configure(e,m,token,room,false);if(!okay){i.fail("native_observer_configuration_invalid");return false;}}return true;}
