 if(i.plan.family==Family::Fish){if(name=="func_806F3A1C"&&n::actor(r,actor,0x4018)&&n::actor(r,other,0x4002)&&n::byte(r,other+0x18)==0x68&&c->r7==0&&c->r6<=2)i.pulses[actor]={other,0,0,++i.serial};for(unsigned m=0;m<i.s.expected;++m){auto& b=i.s.members[m];if(name=="func_805C9D10"&&actor==b.actor&&c->r5==1&&c->r6==1&&i.live(r,m)){auto p=n::word(r,actor+0x1F4);if(n::range(p,0x188)){b.private_data=p;b.initialized=true;}}}}
